import { z } from "zod";

/** Entity identifiers are UUIDs (v7 recommended: time-ordered, generated by IdGenerator). */
export const IdSchema = z.uuid();
export type Id = z.infer<typeof IdSchema>;

/** ISO-8601 UTC timestamp, e.g. 2026-10-30T12:00:00.000Z. */
export const IsoDateTimeSchema = z.iso.datetime();
export type IsoDateTime = z.infer<typeof IsoDateTimeSchema>;

/** Client-chosen key that makes a mutating request safe to retry. Unique per user. */
export const IdempotencyKeySchema = z
  .string()
  .min(8)
  .max(128)
  .regex(/^[A-Za-z0-9_.:-]+$/, "idempotency key may only contain [A-Za-z0-9_.:-]");
export type IdempotencyKey = z.infer<typeof IdempotencyKeySchema>;

/** Opaque pagination cursor. */
export const CursorSchema = z.string().min(1).max(512);

export const PageLimitSchema = z.coerce.number().int().min(1).max(100).default(20);

/** Present on every provider-produced object so mocks can never pass as real data. */
export const SimulatedFlagSchema = z.boolean();

export type JsonPrimitive = string | number | boolean | null;
export type JsonValue = JsonPrimitive | JsonValue[] | { [key: string]: JsonValue };
export const JsonValueSchema: z.ZodType<JsonValue> = z.lazy(() =>
  z.union([
    z.string(),
    z.number().refine(Number.isFinite, "number must be finite"),
    z.boolean(),
    z.null(),
    z.array(JsonValueSchema),
    z.record(z.string(), JsonValueSchema),
  ]),
);
export const JsonObjectSchema = z.record(z.string(), JsonValueSchema);
export type JsonObject = z.infer<typeof JsonObjectSchema>;

export const ZyroPayModeSchema = z.enum(["development", "production"]);
export type ZyroPayMode = z.infer<typeof ZyroPayModeSchema>;
